SELECT medium, COUNT(*) AS piece_count
FROM artworks
GROUP BY medium;

SELECT artwork_id, title, acquisition_cost
FROM artworks
WHERE acquisition_cost > (SELECT AVG(acquisition_cost) FROM artworks);

SELECT p.name AS pet_name, o.first_name || ' ' || o.last_name AS owner_name
FROM pets p
JOIN owners o ON p.owner_id = o.owner_id
WHERE NOT EXISTS (
    SELECT 1 FROM visits v WHERE v.pet_id = p.pet_id
);

SELECT wine_name, varietal, vintage, bottle_price
FROM wines
WHERE color = 'White' AND vintage = 2022;

SELECT customer_type, COUNT(*) AS customer_count
FROM customers
GROUP BY customer_type;

SELECT wine_id, wine_name
FROM wines
WHERE wine_id NOT IN (SELECT wine_id FROM order_items);

SELECT crew_id, full_name, role, department, day_rate, hire_date
FROM crew_members
WHERE hire_date IS NULL OR hire_date = '';

SELECT shoot_id, shoot_date, weather_delay_hours, notes
FROM shoot_days
WHERE weather_delay_hours > 1;

SELECT country, AVG(daily_rate) AS average_daily_rental_cost
FROM locations
GROUP BY country;

SELECT full_name, day_rate
FROM crew_members
WHERE day_rate > (SELECT AVG(day_rate) FROM crew_members);

SELECT turbine_id, turbine_tag, farm_id, model, manufacturer, rated_kw, install_date, status
FROM turbines
WHERE status = 'offline';

SELECT tech_id, full_name
FROM technicians
WHERE tech_id NOT IN (SELECT tech_id FROM work_orders WHERE tech_id IS NOT NULL);

SELECT order_type, COUNT(*) AS job_count
FROM work_orders
GROUP BY order_type;

SELECT tech_id, full_name, hourly_rate
FROM technicians
WHERE hourly_rate > (SELECT AVG(hourly_rate) FROM technicians);

SELECT delivery_id, supplier_id, material_id, delivery_date, weight_kg, truck_plate
FROM deliveries
WHERE contamination_pct IS NULL;

SELECT s.title, h.full_name
FROM shows s
JOIN hosts h ON s.host_id = h.host_id;

SELECT fishing_area, AVG(fuel_liters) AS avg_fuel_per_trip
FROM trips
GROUP BY fishing_area;

SELECT COALESCE(grade, 'No Grade') AS grade, AVG(price_per_kg) AS avg_price_per_kg
FROM catches
GROUP BY grade;

SELECT catch_id, trip_id, species, weight_kg, price_per_kg, grade
FROM catches
WHERE weight_kg > (SELECT AVG(weight_kg) FROM catches);
